import{_ as t,c as e,a2 as l,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"stock/仓位管理/以损定仓比例设置方法.md","filePath":"stock/仓位管理/以损定仓比例设置方法.md"}'),i={name:"stock/仓位管理/以损定仓比例设置方法.md"};function a(s,p,r,_,c,n){return o(),e("div",null,p[0]||(p[0]=[l("<ol><li><p>跳脱风控和止损谈轻仓重仓没有意义。</p></li><li><p>交易的核心在于以确定性的损失博取上不封顶的收益。</p></li><li><p>在损失确定性的前提下，仓位与止损间距成反比。止损间距越小，仓位随之越重；止损间距越大，仓位随之越轻。</p></li><li><p>止损间距=开仓价与关键位置关键K极点价位的价格间距。</p></li></ol><p>上述四点是科学的部分，接下来的两点是艺术的部分。</p><ol><li><p>确定性损失也可以是一个间距。我是设置三个间距等级：A级别即单笔损失不超过总金额1.5%，B级别即单笔损失不超过总金额1%，C级别即单笔损失不超过总金额0.5%。</p></li><li><p>主观认为这一笔概率更高盈利空间更大，则匹配A级别，可以获得更多仓位授权；主观认为这一笔肉很大但概率一般或者概率很高但肉一般，则匹配B级别，获得一般仓位授权；主观认为这一笔盈利空间很大但概率不是很高，则匹配C级别。</p></li></ol><p>在损失确定性的前提下，调控仓位管理水平才可以风轻云淡，谈笑风生。</p><p>脱离风控，随意重仓，虽然不影响胜率和盈亏比，但是交易心理压力会陡然增加，一般人扛不住的。</p><p>交易是逆人性的，因此必须通过设计规矩，规避人性对交易的影响。</p><p>什么是好的制度？</p><p>能让坏人做好事的制度就是好的制度。</p><p>什么是好的交易机制？</p><p>能够规避人性不理性一面对交易负面影响的机制就是好的交易机制。</p>",10)]))}const f=t(i,[["render",a]]);export{m as __pageData,f as default};
